export const COMMANDS = ["push", "pull", "status", "sync"] as const;
export type Command = (typeof COMMANDS)[number];

export interface ClientConfig {
  command: Command;
  dir: string;
  /** Base URL of the server, always with a trailing slash. */
  server: URL;
}

export type CliParseResult = { kind: "help" } | { kind: "command"; config: ClientConfig };

export class UsageError extends Error {
  override name = "UsageError";
}

export const CLIENT_USAGE = `Usage: syncbox <command> <dir> --server <url>

Commands:
  push    Upload files from <dir> that are missing on the server or differ from it
  pull    Download files from the server that are missing or differ locally
  status  Show what push/pull would transfer, without changing anything
  sync    Synchronize in both directions

Options:
  --server <url>  Base URL of the Syncbox server, e.g. http://127.0.0.1:8080
                  (required). Env: SYNCBOX_SERVER
  -h, --help      Show this help.

The command-line flag takes precedence over the environment variable.`;

/**
 * Resolves the client invocation from command-line arguments and environment.
 * `--server` falls back to SYNCBOX_SERVER; an empty variable counts as unset.
 */
export function parseClientArgs(argv: readonly string[], env: NodeJS.ProcessEnv): CliParseResult {
  const positionals: string[] = [];
  let serverRaw: string | undefined;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]!;
    if (arg === "-h" || arg === "--help") {
      return { kind: "help" };
    }
    if (arg === "--server") {
      serverRaw = argv[++i];
      if (serverRaw === undefined) {
        throw new UsageError("--server requires a value");
      }
    } else if (arg.startsWith("--server=")) {
      serverRaw = arg.slice("--server=".length);
    } else if (arg.startsWith("-") && arg !== "-") {
      throw new UsageError(`unknown option: ${arg}`);
    } else {
      positionals.push(arg);
    }
  }

  const [command, dir, ...extra] = positionals;
  if (command === undefined) {
    throw new UsageError("missing command");
  }
  if (!isCommand(command)) {
    throw new UsageError(`unknown command: ${command}`);
  }
  if (dir === undefined || dir === "") {
    throw new UsageError(`${command}: missing <dir>`);
  }
  if (extra.length > 0) {
    throw new UsageError(`unexpected argument: ${extra[0]}`);
  }

  serverRaw ??= env.SYNCBOX_SERVER === "" ? undefined : env.SYNCBOX_SERVER;
  if (serverRaw === undefined || serverRaw === "") {
    throw new UsageError("--server is required (or set SYNCBOX_SERVER)");
  }

  return { kind: "command", config: { command, dir, server: parseServerUrl(serverRaw) } };
}

function isCommand(value: string): value is Command {
  return (COMMANDS as readonly string[]).includes(value);
}

/**
 * Accepts an http(s) URL, optionally with a path prefix the API is mounted
 * under (`http://host/syncbox` → `http://host/syncbox/blobs`).
 */
export function parseServerUrl(raw: string): URL {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new UsageError(`invalid server URL: ${JSON.stringify(raw)} (expected e.g. http://127.0.0.1:8080)`);
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    throw new UsageError(`invalid server URL: ${JSON.stringify(raw)} (only http:// and https:// are supported)`);
  }
  if (url.search !== "" || url.hash !== "") {
    throw new UsageError(`invalid server URL: ${JSON.stringify(raw)} (must not contain a query or fragment)`);
  }
  if (!url.pathname.endsWith("/")) {
    url.pathname += "/";
  }
  return url;
}
import { createHash } from "node:crypto";
import http from "node:http";
import https from "node:https";
import { Transform, type Readable } from "node:stream";
import { pipeline } from "node:stream/promises";

/** A failure to report to the user as is (no stack trace). */
export class ClientError extends Error {
  override name = "ClientError";
}

export interface RemoteBlob {
  key: string;
  size: number;
  sha256: string;
  modified_at: string;
}

/** How long to wait for a TCP connection before giving up on the server. */
const CONNECT_TIMEOUT_MS = 10_000;

interface HttpResponse {
  status: number;
  statusText: string;
  body: Buffer;
}

/** URL of `/blobs/{key}`: each path segment percent-encoded, `/` kept. */
export function blobUrl(server: URL, key: string): URL {
  return new URL(`blobs/${key.split("/").map(encodeURIComponent).join("/")}`, server);
}

/**
 * Thin wrapper over the server's HTTP API (see syncbox-openapi.yaml). Built
 * on node:http rather than fetch(), which refuses to connect to a list of
 * "bad" ports (6000, 10080, ...) a server may well be listening on.
 */
export class SyncboxClient {
  private readonly agent: http.Agent;

  constructor(private readonly server: URL) {
    const Agent = server.protocol === "https:" ? https.Agent : http.Agent;
    this.agent = new Agent({ keepAlive: true });
  }

  /** Releases the kept-alive connections. */
  close(): void {
    this.agent.destroy();
  }

  async list(): Promise<RemoteBlob[]> {
    const what = "GET /blobs";
    const res = await this.request(what, "GET", new URL("blobs", this.server));
    if (res.status !== 200) {
      throw unexpectedStatus(what, res);
    }
    const body = parseJson(what, res);
    if (!Array.isArray(body) || !body.every(isRemoteBlob)) {
      throw new ClientError(`${what}: server returned an unexpected response`);
    }
    return body;
  }

  /**
   * Uploads `body` under `key` and checks that the server stored exactly the
   * bytes that were sent. Returns their SHA-256.
   */
  async put(key: string, body: Readable): Promise<string> {
    const what = `PUT ${key}`;
    const hash = createHash("sha256");
    const hashing = new Transform({
      transform(chunk: Buffer, _encoding, callback) {
        hash.update(chunk);
        callback(null, chunk);
      },
    });
    const res = await this.request(what, "PUT", blobUrl(this.server, key), body, hashing);
    if (res.status !== 201) {
      throw unexpectedStatus(what, res);
    }
    const stored = parseJson(what, res) as { sha256?: unknown } | null;
    const sent = hash.digest("hex");
    if (typeof stored !== "object" || stored === null || stored.sha256 !== sent) {
      throw new ClientError(`${what}: server reports a different SHA-256 than the uploaded content has`);
    }
    return sent;
  }

  /**
   * Downloads the blob stored under `key`. Resolves once the server has
   * answered 200, with the body still to be received: it has to be consumed
   * right away, chunk by chunk. Failures while receiving it are thrown from
   * the iteration as ClientError.
   */
  async get(key: string): Promise<AsyncIterable<Buffer>> {
    const what = `GET ${key}`;
    const res = await this.send(what, "GET", blobUrl(this.server, key));
    if (res.statusCode !== 200) {
      throw unexpectedStatus(what, await this.receive(what, res));
    }
    return this.chunks(what, res);
  }

  /** Sends a request and reads the whole response. */
  private async request(what: string, method: string, url: URL, body?: Readable, via?: Transform): Promise<HttpResponse> {
    return this.receive(what, await this.send(what, method, url, body, via));
  }

  private async receive(what: string, res: http.IncomingMessage): Promise<HttpResponse> {
    const chunks: Buffer[] = [];
    for await (const chunk of this.chunks(what, res)) {
      chunks.push(chunk);
    }
    return { status: res.statusCode ?? 0, statusText: res.statusMessage ?? "", body: Buffer.concat(chunks) };
  }

  private async *chunks(what: string, res: http.IncomingMessage): AsyncGenerator<Buffer> {
    try {
      for await (const chunk of res) {
        yield chunk as Buffer;
      }
    } catch (err) {
      throw this.failed(what, err);
    }
    if (!res.complete) {
      throw this.failed(what, new Error("connection closed before the response was complete"));
    }
  }

  /**
   * Sends a request, streaming `body` through `via` (if given) into it, and
   * resolves with the response as soon as its headers are in.
   */
  private send(what: string, method: string, url: URL, body?: Readable, via?: Transform): Promise<http.IncomingMessage> {
    return new Promise<http.IncomingMessage>((resolve, reject) => {
      const fail = (err: unknown): void => {
        req.destroy();
        reject(this.failed(what, err));
      };

      const transport = url.protocol === "https:" ? https : http;
      const req = transport.request(
        url,
        {
          method,
          agent: this.agent,
          headers: body === undefined ? {} : { "Content-Type": "application/octet-stream" },
        },
        (res) => {
          // Errors reach whoever reads the body (through the stream's state);
          // this only keeps one that comes before reading starts, or after it
          // was abandoned, from being an uncaught 'error' event.
          res.on("error", () => {});
          resolve(res);
        },
      );
      req.on("error", fail);

      // Only the connection setup is time-limited: a server that is merely
      // slow (hashing a large store for GET /blobs, say) is not an error.
      req.on("socket", (socket) => {
        if (!socket.connecting) return;
        const timer = setTimeout(() => fail(new Error(`no connection within ${CONNECT_TIMEOUT_MS / 1000}s`)), CONNECT_TIMEOUT_MS);
        socket.once("connect", () => clearTimeout(timer));
        socket.once("close", () => clearTimeout(timer));
      });

      if (body === undefined) {
        req.end();
      } else {
        const upload = via === undefined ? pipeline(body, req) : pipeline(body, via, req);
        upload.catch(fail);
      }
    });
  }

  private failed(what: string, err: unknown): ClientError {
    return err instanceof ClientError ? err : new ClientError(`${what}: request to ${this.server.origin} failed: ${describeError(err)}`);
  }
}

function isRemoteBlob(value: unknown): value is RemoteBlob {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return typeof v.key === "string" && typeof v.size === "number" && typeof v.sha256 === "string";
}

function parseJson(what: string, res: HttpResponse): unknown {
  try {
    return JSON.parse(res.body.toString("utf8"));
  } catch {
    throw new ClientError(`${what}: server returned a response that is not valid JSON`);
  }
}

function unexpectedStatus(what: string, res: HttpResponse): ClientError {
  let detail = "";
  try {
    const parsed = JSON.parse(res.body.toString("utf8")) as { error?: unknown };
    if (typeof parsed.error === "string") detail = `: ${parsed.error}`;
  } catch {
    // Not the server's JSON error format: the status alone has to do.
  }
  return new ClientError(`${what}: server responded ${res.status} ${res.statusText}${detail}`.trimEnd());
}

/**
 * A readable reason for a failed request. With several addresses to try
 * (localhost → ::1 and 127.0.0.1), connect errors come as an AggregateError
 * without a message of its own.
 */
function describeError(err: unknown): string {
  if (err instanceof AggregateError && err.errors.length > 0) {
    return describeError(err.errors[0]);
  }
  if (err instanceof Error) {
    return err.message || ((err as NodeJS.ErrnoException).code ?? err.name);
  }
  return String(err);
}
import { createHash } from "node:crypto";
import { createReadStream } from "node:fs";
import { readdir, stat } from "node:fs/promises";
import { join } from "node:path";

import { decodeUtf8 } from "./blobs.js";
import { ClientError, type RemoteBlob, type SyncboxClient } from "./client.js";

export interface LocalFile {
  /** Relative POSIX path inside the scanned directory: the blob key. */
  key: string;
  path: string;
  size: number;
}

export interface Reporter {
  info(line: string): void;
  warn(line: string): void;
}

export interface PushSummary {
  uploaded: string[];
  unchanged: string[];
  /** Directory entries that can't be pushed (links, special files, bad names). */
  skipped: number;
}

/** What push would do: worked out without changing anything. */
export interface PushPlan {
  /** Files the server doesn't have, or has with a different SHA-256. */
  upload: LocalFile[];
  unchanged: string[];
  skipped: number;
}

/**
 * Uploads every file under `dir` that the server doesn't have or has with a
 * different SHA-256; files the server already has with the same content are
 * left alone. Nothing on the server is deleted. Stops at the first failure.
 */
export async function push(dir: string, client: SyncboxClient, reporter: Reporter): Promise<PushSummary> {
  await assertDirectory(dir);
  // Ask the server first: if it is unreachable, there's no point in hashing.
  const plan = await planPush(dir, await client.list(), reporter);

  const summary: PushSummary = { uploaded: [], unchanged: plan.unchanged, skipped: plan.skipped };
  for (const file of plan.upload) {
    await client.put(file.key, createReadStream(file.path));
    summary.uploaded.push(file.key);
    reporter.info(`uploaded ${file.key}`);
  }
  return summary;
}

/**
 * Compares the files under `dir` with the server's list, sorted by key.
 * Only reads `dir`. `hash` lets a caller that compares the same files more
 * than once hash each of them only once.
 */
export async function planPush(
  dir: string,
  remoteList: readonly RemoteBlob[],
  reporter: Reporter,
  hash: (file: LocalFile) => Promise<string> = hashFile,
): Promise<PushPlan> {
  const remote = new Map(remoteList.map((blob) => [blob.key, blob]));
  const { files, skipped } = await scanDir(dir, reporter);

  const plan: PushPlan = { upload: [], unchanged: [], skipped };
  for (const file of files) {
    const existing = remote.get(file.key);
    // A different size already means different content: no need to hash.
    if (existing !== undefined && existing.size === file.size && (await hash(file)) === existing.sha256) {
      plan.unchanged.push(file.key);
    } else {
      plan.upload.push(file);
    }
  }
  return plan;
}

export async function assertDirectory(dir: string): Promise<void> {
  let st;
  try {
    st = await stat(dir);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") throw new ClientError(`${dir}: no such directory`);
    throw new ClientError(`${dir}: ${(err as Error).message}`);
  }
  if (!st.isDirectory()) throw new ClientError(`${dir}: not a directory`);
}

/**
 * Lists the regular files under `root` recursively, sorted by key. Symbolic
 * links and special files are skipped with a warning, and so are names that
 * aren't valid UTF-8, since no key can represent them. Empty directories
 * have no blob counterpart and simply produce nothing.
 */
export async function scanDir(root: string, reporter: Reporter): Promise<{ files: LocalFile[]; skipped: number }> {
  const files: LocalFile[] = [];
  let skipped = 0;

  const walk = async (dir: string, prefix: string): Promise<void> => {
    let entries;
    try {
      entries = await readdir(dir, { withFileTypes: true, encoding: "buffer" });
    } catch (err) {
      throw new ClientError(`cannot read directory ${prefix === "" ? "." : prefix}: ${(err as Error).message}`);
    }
    for (const entry of entries) {
      const name = decodeUtf8(entry.name);
      if (name === undefined) {
        reporter.warn(`skipping ${prefix}${entry.name.toString("utf8")}: name is not valid UTF-8`);
        skipped++;
        continue;
      }
      const key = prefix + name;
      const path = join(dir, name);
      if (entry.isDirectory()) {
        await walk(path, `${key}/`);
      } else if (entry.isFile()) {
        let st;
        try {
          st = await stat(path);
        } catch (err) {
          throw new ClientError(`cannot read ${key}: ${(err as Error).message}`);
        }
        files.push({ key, path, size: st.size });
      } else {
        reporter.warn(`skipping ${key}: ${entry.isSymbolicLink() ? "symbolic link" : "not a regular file"}`);
        skipped++;
      }
    }
  };

  await walk(root, "");
  files.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  return { files, skipped };
}

export async function hashFile(file: LocalFile): Promise<string> {
  const hash = createHash("sha256");
  try {
    for await (const chunk of createReadStream(file.path)) {
      hash.update(chunk as Buffer);
    }
  } catch (err) {
    throw new ClientError(`cannot read ${file.key}: ${(err as Error).message}`);
  }
  return hash.digest("hex");
}
import { createHash, randomUUID } from "node:crypto";
import { lstat, mkdir, open, rename, rm } from "node:fs/promises";
import { dirname, join } from "node:path";

import { ClientError, type RemoteBlob, type SyncboxClient } from "./client.js";
import { assertDirectory, hashFile, type LocalFile, type Reporter } from "./push.js";

export interface PullSummary {
  downloaded: string[];
  unchanged: string[];
  /** Blobs that can't be pulled (unusable keys, links or special files in the way). */
  skipped: number;
}

/** What pull would do: worked out without changing anything. */
export interface PullPlan {
  /** Blobs missing under the directory or differing from the local file, sorted by key. */
  download: { blob: RemoteBlob; target: string }[];
  /** Blobs pull can't write because a directory is where the file belongs, or a file where a directory belongs. */
  blocked: { key: string; reason: string }[];
  unchanged: string[];
  skipped: number;
}

/** What is at a key's path in the local directory. */
type LocalEntry =
  | { kind: "missing" }
  | ({ kind: "file" } & LocalFile)
  | { kind: "skip"; reason: string }
  | { kind: "blocked"; reason: string };

/**
 * Downloads every blob the server has that is missing under `dir` or differs
 * from the local file by SHA-256, creating subdirectories as needed; files
 * that already have the server's content are left alone. Nothing local is
 * deleted. Each file is written to a temporary file next to it and renamed
 * into place, so it is never left half-written. Stops at the first failure,
 * and fails before downloading anything if some blob can't be written.
 */
export async function pull(dir: string, client: SyncboxClient, reporter: Reporter): Promise<PullSummary> {
  await assertDirectory(dir);
  const plan = await planPull(dir, await client.list(), reporter);
  const blocked = plan.blocked[0];
  if (blocked !== undefined) {
    throw new ClientError(`cannot write ${blocked.key}: ${blocked.reason}`);
  }

  const summary: PullSummary = { downloaded: [], unchanged: plan.unchanged, skipped: plan.skipped };
  for (const { blob, target } of plan.download) {
    await download(client, blob, target);
    summary.downloaded.push(blob.key);
    reporter.info(`downloaded ${blob.key}`);
  }
  return summary;
}

/**
 * Compares the server's list with what is under `dir`. Only reads `dir`.
 * `hash` lets a caller that compares the same files more than once hash
 * each of them only once.
 */
export async function planPull(
  dir: string,
  remoteList: readonly RemoteBlob[],
  reporter: Reporter,
  hash: (file: LocalFile) => Promise<string> = hashFile,
): Promise<PullPlan> {
  const remote = [...remoteList].sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));

  const plan: PullPlan = { download: [], blocked: [], unchanged: [], skipped: 0 };
  for (const blob of remote) {
    const segments = keySegments(blob.key);
    if (segments === undefined) {
      reporter.warn(`skipping ${JSON.stringify(blob.key)}: not a relative path inside the directory`);
      plan.skipped++;
      continue;
    }
    const local = await inspect(dir, blob.key, segments);
    if (local.kind === "skip") {
      reporter.warn(`skipping ${blob.key}: ${local.reason}`);
      plan.skipped++;
    } else if (local.kind === "blocked") {
      plan.blocked.push({ key: blob.key, reason: local.reason });
    } else if (local.kind === "file" && local.size === blob.size && (await hash(local)) === blob.sha256) {
      // A different size already means different content: no need to hash.
      plan.unchanged.push(blob.key);
    } else {
      plan.download.push({ blob, target: join(dir, ...segments) });
    }
  }
  return plan;
}


/**
 * Splits a key from the server's list into path segments, or returns
 * undefined if it isn't a relative POSIX path that stays inside the
 * directory. The server refuses to store such keys; this doesn't rely on it.
 */
function keySegments(key: string): string[] | undefined {
  if (key === "" || key.startsWith("/") || key.includes("\0")) return undefined;
  // Lone surrogates would end up as U+FFFD in the file name: another key.
  if (Buffer.from(key, "utf8").toString("utf8") !== key) return undefined;
  const segments = key.split("/");
  if (segments.some((s) => s === "" || s === "." || s === "..")) return undefined;
  return segments;
}

