132	#!/usr/bin/env bash
133	# Runs the Syncbox CLI client (`syncbox`) in a Docker container (via docker
134	# compose) and exits with its exit code.
135	#
136	#   run-client <push|pull|status|sync> <dir> --server <url>
137	#
138	# Arguments are forwarded to the client as given, except <dir>: that host
139	# directory is bind-mounted into the container at /work and the client gets
140	# that path instead. --server falls back to SYNCBOX_SERVER. The container
141	# shares the host's network, so http://127.0.0.1:<port> reaches a server
142	# started with run-server.
143	set -euo pipefail
144	
145	repo="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
146	mount_point=/work
147	
148	# Only the command and <dir> (the first two positional arguments) are picked
149	# out here; validating everything else is left to the client, so its usage
150	# errors stay the same.
151	args=()
152	command=""
153	dir=""
154	positional=0
155	while [[ $# -gt 0 ]]; do
156	  case "$1" in
157	    --server)
158	      args+=("$1")
159	      shift
160	      if [[ $# -gt 0 ]]; then args+=("$1"); shift; fi
161	      ;;
162	    -?*) args+=("$1"); shift ;;
163	    *)
164	      positional=$((positional + 1))
165	      if (( positional == 1 )); then
166	        command="$1"
167	      fi
168	      if (( positional == 2 )) && [[ -n "$1" ]]; then
169	        dir="$1"
170	        args+=("$mount_point")
171	      else
172	        args+=("$1")
173	      fi
174	      shift
175	      ;;
176	  esac
177	done
178	
179	cleanup=""
180	if [[ -n "$dir" ]]; then
181	  if [[ ! -e "$dir" ]]; then
182	    echo "run-client: $dir: no such directory" >&2
183	    exit 1
184	  fi
185	  if [[ ! -d "$dir" ]]; then
186	    echo "run-client: $dir: not a directory" >&2
187	    exit 1
188	  fi
189	  host_dir="$(cd -- "$dir" && pwd -P)"
190	else
191	  # No directory to work on (--help, usage errors): mount an empty one.
192	  host_dir="$(mktemp -d)"
193	  cleanup="$host_dir"
194	fi
195	trap '[[ -z "$cleanup" ]] || rmdir -- "$cleanup"' EXIT
196	
197	export SYNCBOX_CLIENT_DIR="$host_dir"
198	# status only reads <dir>: mount it read-only, so it can't change it even by mistake.
199	export SYNCBOX_CLIENT_DIR_RO=false
200	[[ "$command" != status ]] || SYNCBOX_CLIENT_DIR_RO=true
201	export SYNCBOX_UID="$(id -u)"
202	export SYNCBOX_GID="$(id -g)"
203	
204	project="$(basename "$repo" | tr '[:upper:]' '[:lower:]' | tr -c 'a-z0-9_\n-' '-')"
