206	
207	# --build is a no-op on a warm cache and picks up source changes otherwise;
208	# --progress quiet keeps the build output from mixing with the client's.
209	status=0
210	docker compose --progress quiet --project-directory "$repo" -f "$repo/compose.yaml" -p "$project" \
211	  run --rm --build -T client ${args[@]+"${args[@]}"} || status=$?
212	exit "$status"
