114	export function runSyncbox(args: string[], env: NodeJS.ProcessEnv = {}): Promise<Result> {
115	  // Clean environment, so a SYNCBOX_SERVER from the outside can't leak in.
116	  const child = spawn(SYNCBOX, args, { env: { PATH: process.env.PATH, ...env }, stdio: ["ignore", "pipe", "pipe"] });
117	  let stdout = "";
118	  let stderr = "";
119	  child.stdout.setEncoding("utf8").on("data", (c: string) => (stdout += c));
120	  child.stderr.setEncoding("utf8").on("data", (c: string) => (stderr += c));
121	  return once(child, "exit").then(([code]) => ({ code: code as number | null, stdout, stderr }));
122	}
