500	async function snapshot(root: string): Promise<Record<string, string>> {
501	  const result: Record<string, string> = {};
502	  const rootSt = await lstat(root);
503	  result["."] = `dir ${rootSt.mtimeMs}`;
504	  for (const rel of (await readdir(root, { recursive: true })).sort()) {
505	    const path = join(root, rel);
506	    const st = await lstat(path);
507	    if (st.isFile()) {
508	      result[rel] = `file ${st.size} ${st.mtimeMs} ${sha256(await readFile(path))}`;
509	    } else if (st.isSymbolicLink()) {
510	      result[rel] = `link ${st.mtimeMs}`;
511	    } else {
512	      result[rel] = `${st.isDirectory() ? "dir" : "other"} ${st.mtimeMs}`;
513	    }
514	  }
515	  return result;
516	}
