1016	export function parseKey(raw: string): string {
1017	  // req.url carries the request-target bytes as latin1 characters.
1018	  const key = decodeUtf8(percentDecode(Buffer.from(raw, "latin1")));
1019	  if (key === undefined) throw new InvalidKeyError("key is not valid UTF-8");
1020	  if (key === "") throw new InvalidKeyError("key is empty");
1021	  if (key.includes("\0")) throw new InvalidKeyError("key contains a NUL byte");
1022	  if (key.startsWith("/")) throw new InvalidKeyError("key must be a relative path");
1023	  for (const segment of key.split("/")) {
1024	    if (segment === "" || segment === "." || segment === "..") {
1025	      throw new InvalidKeyError("key contains an empty, '.' or '..' path segment");
1026	    }
1027	    if (Buffer.byteLength(segment) > MAX_SEGMENT_BYTES) {
