1043	function percentDecode(input: Buffer): Buffer {
1044	  const out = Buffer.alloc(input.length);
1045	  let n = 0;
1046	  for (let i = 0; i < input.length; i++) {
1047	    const byte = input[i]!;
1048	    if (byte !== 0x25 /* % */) {
1049	      out[n++] = byte;
1050	      continue;
1051	    }
1052	    const hex = input.subarray(i + 1, i + 3).toString("latin1");
1053	    if (!/^[0-9a-fA-F]{2}$/.test(hex)) {
1054	      throw new InvalidKeyError("key contains a malformed percent-escape");
1055	    }
1056	    out[n++] = parseInt(hex, 16);
1057	    i += 2;
1058	  }
1059	  return out.subarray(0, n);
1060	}
